use std::sync::{Arc, Mutex};
use std::thread;

struct Shared {
    m: Mutex<i32>,
}

fn w1(shared: Arc<Shared>) {
    {
        let mut guard = shared.m.lock().unwrap();
        *guard = *guard + 1;
    }
}

fn w2(shared: Arc<Shared>) {
    {
        let mut guard = shared.m.lock().unwrap();
        *guard = *guard + 1;
    }
}

