use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn w1(s: Arc<Semaphore>) {
    let p1 = s.acquire();
    p1.release();
    let p2 = s.acquire();
    p2.release();
}

fn w2(s: Arc<Semaphore>) {
    let p1 = s.acquire();
    p1.release();
    let p2 = s.acquire();
    p2.release();
}

fn main() {
    let s = Semaphore::new(1);

    let s1 = Arc::clone(&s);
    let s2 = Arc::clone(&s);

    let h1 = thread::spawn(move || w1(s1));
    let h2 = thread::spawn(move || w2(s2));

    h1.join().unwrap();
    h2.join().unwrap();

    println!("DONE done=1");
}
```

