        {
          "name": "worker",
          "kind": "normal",
          "form": "closure",
          "body": [
            {
              "sid": "s1",
              "kind": "return"
            }
          ]
        },
        {
          "name": "main",
          "kind": "normal",
          "body": [
            {
              "sid": "s1",
              "kind": "spawn",
              "func": "main::worker",
              "handle": "w1"
            },
            {
              "sid": "s2",
              "kind": "join",
              "handle": "w1"
            },
            {
              "sid": "s3",
